import{_ as i,a0 as p,w as d,s as r,I as l,x as s,a1 as t,A as n,ao as o}from"./chunks/framework.C16IyNjs.js";import"./chunks/theme.CClUzVyq.js";const S=JSON.parse('{"title":"給大家安利一下 PowerShell | LCTT x X-CMD","titleTemplate":false,"description":"給大家安利一下 PowerShell | LCTT (201903) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"給大家安利一下 PowerShell | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"給大家安利一下 PowerShell | LCTT (201903) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"201903/20180206 Power(Shell) to the people","title":"給大家安利一下 PowerShell","tag":"201903","desc":""},"relativePath":"201903/20180206 Power(Shell) to the people.md","filePath":"[post].md"}'),h={name:"201903/20180206 Power(Shell) to the people.md"};function u(g,e,b,m,k,c){const a=p("Link");return d(),r("div",null,[e[41]||(e[41]=l("h1",{id:"給大家安利一下-powershell",tabindex:"-1"},[s("給大家安利一下 PowerShell "),l("a",{class:"header-anchor",href:"#給大家安利一下-powershell","aria-label":"Permalink to “給大家安利一下 PowerShell”"},"​")],-1)),e[42]||(e[42]=l("blockquote",null,[l("p",null,"代碼更簡潔、腳本更清晰、跨平台一致性等好處是讓 Linux 和 OS X 用户喜愛 PowerShell 的原因。")],-1)),e[43]||(e[43]=l("p",null,[l("img",{src:"https://opensource.com/sites/default/files/styles/image-full-size/public/lead-images/BUSINESS_lightbulbs.png?itok=pwp22hTw",alt:""})],-1)),l("p",null,[e[4]||(e[4]=s("今年（2018）早些時候，",-1)),t(a,{href:"https://github.com/PowerShell/PowerShell/blob/master/README.md"},{default:n(()=>[...e[0]||(e[0]=[s("Powershell Core",-1)])]),_:1}),e[5]||(e[5]=s(" 以 ",-1)),t(a,{href:"https://spdx.org/licenses/MIT"},{default:n(()=>[...e[1]||(e[1]=[s("MIT",-1)])]),_:1}),e[6]||(e[6]=s(" 開源協議發佈了",-1)),t(a,{href:"https://blogs.msdn.microsoft.com/powershell/2018/01/10/powershell-core-6-0-generally-available-ga-and-supported/"},{default:n(()=>[...e[2]||(e[2]=[s("正式可用版（GA）",-1)])]),_:1}),e[7]||(e[7]=s("。PowerShell 算不上是新技術。自 2006 年為 Windows 發佈了第一版 PowerShell 以來，PowerShell 的創建者在",-1)),t(a,{href:"http://www.jsnover.com/Docs/MonadManifesto.pdf"},{default:n(()=>[...e[3]||(e[3]=[s("結合了",-1)])]),_:1}),e[8]||(e[8]=s(" Unⅸ shell 的強大和靈活的同時也在彌補他們所意識到的缺點，特別是從組合命令中獲取值時所要進行的文本操作。",-1))]),e[44]||(e[44]=o(`<p>在發佈了 5 個主要版本之後，PowerShell 已經可以在所有主流操作系統上（包括 OS X 和 Linux）本地運行同樣創新的 shell 和命令列環境。一些人（應該説是大多數人）可能依舊在嘲弄這位誕生於 Windows 的闖入者的大膽和冒失：為那些遠古以來（從千禧年開始算不算？）便存在着強大的 shell 環境的平台引薦自己。在本帖中，我希望可以將 PowerShell 的優勢介紹給大家，甚至是那些經驗老道的用户。</p><h3 id="跨平台一致性" tabindex="-1">跨平台一致性 <a class="header-anchor" href="#跨平台一致性" aria-label="Permalink to “跨平台一致性”">​</a></h3><p>如果你計劃將腳本從一個執行環境遷移到另一個平台時，你需要確保只使用了那些在兩個平台下都起作用的命令和語法。比如在 GNU 系統中，你可以通過以下方式獲取昨天的日期：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>date --date=&quot;1 day ago&quot;</span></span></code></pre></div><p>在 BSD 系統中（比如 OS X），上述語法將沒辦法工作，因為 BSD 的 date 工具需要以下語法：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>date -v -1d</span></span></code></pre></div><p>因為 PowerShell 具有寬鬆的許可證，並且在所有的平台都有構建，所以你可以把 PowerShell 和你的應用一起打包。因此，當你的腳本運行在目標系統中時，它們會運行在一樣的 shell 環境中，使用與你的測試環境中同樣的命令實現。</p><h3 id="對象和結構化數據" tabindex="-1">對象和結構化數據 <a class="header-anchor" href="#對象和結構化數據" aria-label="Permalink to “對象和結構化數據”">​</a></h3><p>*nix 命令和工具依賴於你使用和操控非結構化數據的能力。對於那些長期活在 <code>sed</code>、 <code>grep</code> 和 <code>awk</code> 環境下的人們來説，這可能是小菜一碟，但現在有更好的選擇。</p><p>讓我們使用 PowerShell 重寫那個獲取昨天日期的實例。為了獲取當前日期，使用 <code>Get-Date</code> cmdlet（讀作 “commandlet”）：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>&gt; Get-Date                        </span></span>
<span class="line"><span></span></span>
<span class="line"><span>Sunday, January 21, 2018 8:12:41 PM</span></span></code></pre></div><p>你所看到的輸出實際上並不是一個文本字符串。不如説，這是 .Net Core 對象的一個字符串表現形式。就像任何 OOP 環境中的對象一樣，它具有類型以及你可以調用的方法。</p><p>讓我們來證明這一點：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>&gt; $(Get-Date).GetType().FullName</span></span>
<span class="line"><span>System.DateTime</span></span></code></pre></div>`,14)),l("p",null,[e[10]||(e[10]=l("code",null,"$(...)",-1)),e[11]||(e[11]=s(" 語法就像你所期望的 POSIX shell 中那樣，計算括弧中的命令然後替換整個表達式。但是在 PowerShell 中，這種表達式中的 ",-1)),e[12]||(e[12]=l("code",null,"$",-1)),e[13]||(e[13]=s(" 是可選的。並且，最重要的是，結果是一個 .Net 對象，而不是文本。因此我們可以調用該對象中的 ",-1)),e[14]||(e[14]=l("code",null,"GetType()",-1)),e[15]||(e[15]=s(" 方法來獲取該對象類型（類似於 Java 中的 ",-1)),e[16]||(e[16]=l("code",null,"Class",-1)),e[17]||(e[17]=s(" 對象），",-1)),e[18]||(e[18]=l("code",null,"FullName",-1)),e[19]||(e[19]=s()),t(a,{href:"https://docs.microsoft.com/en-us/dotnet/csharp/programming-guide/classes-and-structs/properties"},{default:n(()=>[...e[9]||(e[9]=[s("屬性",-1)])]),_:1}),e[20]||(e[20]=s(" 則用來獲取該類型的全稱。",-1))]),e[45]||(e[45]=o(`<p>那麼，這種對象導向的 shell 是如何讓你的工作變得更加簡單呢？</p><p>首先，你可將任何對象排進 <code>Get-Member</code> cmdlet 來查看它提供的所有方法和屬性。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>&gt; (Get-Date) | Get-Member</span></span>
<span class="line"><span>PS /home/yevster/Documents/ArticlesInProgress&gt; $(Get-Date) | Get-Member         </span></span>
<span class="line"><span></span></span>
<span class="line"><span></span></span>
<span class="line"><span>   TypeName: System.DateTime</span></span>
<span class="line"><span></span></span>
<span class="line"><span>Name                 MemberType     Definition                                 </span></span>
<span class="line"><span>----                 ----------     ----------                                 </span></span>
<span class="line"><span>Add                  Method         datetime Add(timespan value)               </span></span>
<span class="line"><span>AddDays              Method         datetime AddDays(double value)             </span></span>
<span class="line"><span>AddHours             Method         datetime AddHours(double value)            </span></span>
<span class="line"><span>AddMilliseconds      Method         datetime AddMilliseconds(double value)     </span></span>
<span class="line"><span>AddMinutes           Method         datetime AddMinutes(double value)          </span></span>
<span class="line"><span>AddMonths            Method         datetime AddMonths(int months)             </span></span>
<span class="line"><span>AddSeconds           Method         datetime AddSeconds(double value)          </span></span>
<span class="line"><span>AddTicks             Method         datetime AddTicks(long value)              </span></span>
<span class="line"><span>AddYears             Method         datetime AddYears(int value)               </span></span>
<span class="line"><span>CompareTo            Method         int CompareTo(System.Object value), int ...</span></span></code></pre></div><p>你可以很快的看到 DateTime 對象具有一個 <code>AddDays</code> 方法，從而可以使用它來快速的獲取昨天的日期：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>&gt; (Get-Date).AddDays(-1)</span></span>
<span class="line"><span></span></span>
<span class="line"><span>Saturday, January 20, 2018 8:24:42 PM</span></span></code></pre></div><p>為了做一些更刺激的事，讓我們調用 Yahoo 的天氣服務（因為它不需要 API 令牌）然後獲取你的本地天氣。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$city=&quot;Boston&quot;</span></span>
<span class="line"><span>$state=&quot;MA&quot;</span></span>
<span class="line"><span>$url=&quot;https://query.yahooapis.com/v1/public/yql?q=select%20*%20from%20weather.forecast%20where%20woeid%20in%20(select%20woeid%20from%20geo.places(1)%20where%20text%3D%22\${city}%2C%20\${state}%22)&amp;format=json&amp;env=store%3A%2F%2Fdatatables.org%2Falltableswithkeys&quot;</span></span></code></pre></div><p>現在，我們可以使用老派的方法然後直接運行 <code>curl $url</code> 來獲取 JSON 二進制對象，或者……</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$weather=(Invoke-RestMethod $url)</span></span></code></pre></div><p>如果你查看了 <code>$weather</code> 類型（運行 <code>echo $weather.GetType().FullName</code>），你將會發現它是一個 <code>PSCustomObject</code>。這是一個用來反射 JSON 結構的動態對象。</p><p>然後 PowerShell 可以通過 tab 補齊來幫助你完成命令輸入。只需要輸入 <code>$weather.</code>（確報包含了 <code>.</code>）然後按下 <code>Tab</code> 鍵。你將看到所有根級別的 JSON 鍵。輸入其中的一個，然後跟上 <code>.</code> ，再一次按下 <code>Tab</code> 鍵，你將看到它所有的子鍵（如果有的話）。</p><p>因此，你可以輕易的導航到你所想要的數據：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>&gt; echo $weather.query.results.channel.atmosphere.pressure                         </span></span>
<span class="line"><span>1019.0</span></span>
<span class="line"><span></span></span>
<span class="line"><span>&gt; echo $weather.query.results.channel.wind.chill                                 41</span></span></code></pre></div><p>並且如果你有非結構化的 JSON 或 CSV 數據（通過外部命令返回的），只需要將它相應的排進 <code>ConverFrom-Json</code> 或 <code>ConvertFrom-CSV</code> cmdlet，然後你可以得到一個漂亮乾淨的對象。</p><h3 id="計算-vs-自動化" tabindex="-1">計算 vs. 自動化 <a class="header-anchor" href="#計算-vs-自動化" aria-label="Permalink to “計算 vs. 自動化”">​</a></h3><p>我們使用 shell 用於兩種目的。一個是用於計算，運行獨立的命令然後手動響應它們的輸出。另一個是自動化，通過寫腳本執行多個命令，然後以編程的方式相應它們的輸出。</p><p>我們大多數人都能發現這兩種目的在 shell 上的不同且互相沖突的要求。計算任務要求 shell 簡潔明瞭。用户輸入的越少越好。但如果用户輸入對其他用户來説幾乎難以理解，那這一點就不重要了。腳本，從另一個角度來講是代碼。可讀性和可維護性是關鍵。這一方面，POSIX 工具通常是失敗的。雖然一些命令通常會為它們的參數提供簡潔明瞭的語法（如：<code>-f</code> 和 <code>--force</code>），但是命令名字本身就不簡潔明瞭。</p><p>PowerShell 提供了幾個機制來消除這種浮士德式的平衡。</p><p>首先，tab 補齊可以消除鍵入參數名的需要。比如：鍵入 <code>Get-Random -Mi</code>，按下 <code>Tab</code> 然後 PowerShell 將會為你完成參數：<code>Get-Random -Minimum</code>。但是如果你想更簡潔一些，你甚至不需要按下 <code>Tab</code>。如下所示，PowerShell 可以理解：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>Get-Random -Mi 1 -Ma 10</span></span></code></pre></div><p>因為 <code>Mi</code> 和 <code>Ma</code> 每一個都具有獨立不同的補齊。</p><p>你可能已經留意到所有的 PowerShell cmdlet 名稱具有動名詞結構。這有助於腳本的可讀性，但是你可能不想一而再、再而三的鍵入 <code>Get-</code>。所以並不需要！如果你之間鍵入了一個名詞而沒有動詞的話，PowerShell 將查找帶有該名詞的 <code>Get-</code> 命令。</p><blockquote><p>小心：儘管 PowerShell 不區分大小寫，但在使用 PowerShell 命令是時，名詞首字母大寫是一個好習慣。比如，鍵入 <code>date</code> 將會調用系統中的 <code>date</code> 工具。鍵入 <code>Date</code> 將會調用 PowerShell 的 <code>Get-Date</code> cmdlet。</p></blockquote><p>如果這還不夠，PowerShell 還提供了別名，用來創建簡單的名字。比如，如果鍵入 <code>alias -name cd</code>，你將會發現 <code>cd</code> 在 PowerShell 實際上時 <code>Set-Location</code> 命令的別名。</p><p>所以回顧以下 —— 你可以使用強大的 tab 補全、別名，和名詞補全來保持命令名詞簡潔、自動化和一致性參數名截斷，與此同時還可以享受豐富、可讀的語法格式。</p><h3 id="那麼-你看呢" tabindex="-1">那麼……你看呢？ <a class="header-anchor" href="#那麼-你看呢" aria-label="Permalink to “那麼……你看呢？”">​</a></h3>`,26)),l("p",null,[e[22]||(e[22]=s("這些只是 PowerShell 的一部分優勢。還有更多特性和 cmdlet，我還沒討論（如果你想弄哭 ",-1)),e[23]||(e[23]=l("code",null,"grep",-1)),e[24]||(e[24]=s(" 的話，可以查看 ",-1)),t(a,{href:"https://docs.microsoft.com/en-us/powershell/module/microsoft.powershell.core/where-object?view=powershell-6"},{default:n(()=>[...e[21]||(e[21]=[s("Where-Object",-1)])]),_:1}),e[25]||(e[25]=s(" 或其別稱 ",-1)),e[26]||(e[26]=l("code",null,"?",-1)),e[27]||(e[27]=s("）。如果你有點懷舊的話，PowerShell 可以為你加載原來的本地工具。但是給自己足夠的時間來適應 PowerShell 面向對象 cmdlet 的世界，然後你將發現自己會選擇忘記回去的路。",-1))]),e[46]||(e[46]=l("hr",null,null,-1)),l("p",null,[e[29]||(e[29]=s("via: ",-1)),t(a,{href:"https://opensource.com/article/18/2/powershell-people"},{default:n(()=>[...e[28]||(e[28]=[s("https://opensource.com/article/18/2/powershell-people",-1)])]),_:1})]),l("p",null,[e[33]||(e[33]=s("作者：",-1)),t(a,{href:"https://opensource.com/users/yevster"},{default:n(()=>[...e[30]||(e[30]=[s("Yev Bronshteyn",-1)])]),_:1}),e[34]||(e[34]=s(" 譯者：",-1)),t(a,{href:"https://github.com/sanfusu"},{default:n(()=>[...e[31]||(e[31]=[s("sanfusu",-1)])]),_:1}),e[35]||(e[35]=s(" 校對：",-1)),t(a,{href:"https://github.com/wxy"},{default:n(()=>[...e[32]||(e[32]=[s("wxy",-1)])]),_:1})]),l("p",null,[e[38]||(e[38]=s("本文由 ",-1)),t(a,{href:"https://github.com/LCTT/TranslateProject"},{default:n(()=>[...e[36]||(e[36]=[s("LCTT",-1)])]),_:1}),e[39]||(e[39]=s(" 原創編譯，",-1)),t(a,{href:"https://linux.cn/"},{default:n(()=>[...e[37]||(e[37]=[s("Linux中國",-1)])]),_:1}),e[40]||(e[40]=s(" 榮譽推出",-1))])])}const y=i(h,[["render",u]]);export{S as __pageData,y as default};
